package ru.screenrecorder.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.media.*;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.util.*;
public final class MainActivity extends Activity {
 static final int BG=0xff111b23,TEXT=0xfff4f8fc,MINT=0xff70edbb;LinearLayout body;TextView state,meter;Switch mic,internal;SeekBar gain;Spinner quality;android.content.SharedPreferences prefs;Handler handler=new Handler();boolean resumed;String shown="";
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("settings",0);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);home();}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}float font(){return prefs.getInt("font",100)/100f;}
 TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size*font());v.setTextColor(TEXT);v.setPadding(0,dp(8),0,dp(8));return v;}
 GradientDrawable round(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(16));return d;}
 void base(String title){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(22),dp(26),dp(22),dp(30));scroll.addView(body);setContentView(scroll);LinearLayout top=new LinearLayout(this);TextView heading=text(title,26);top.addView(heading,new LinearLayout.LayoutParams(0,-2,1));TextView fonts=text("Шрифт ▾",12);fonts.setContentDescription("Размер шрифта");fonts.setOnClickListener(v->{PopupMenu p=new PopupMenu(this,fonts);for(int n:new int[]{100,125,150,175,200})p.getMenu().add(n+"%").setOnMenuItemClickListener(x->{prefs.edit().putInt("font",n).apply();home();return true;});p.show();});top.addView(fonts);body.addView(top);}
 Button button(String s,Runnable action,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(18*font());b.setTextColor(primary?BG:TEXT);b.setBackground(round(primary?MINT:0xff253540));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(58));lp.setMargins(0,dp(9),0,dp(6));body.addView(b,lp);b.setOnClickListener(v->action.run());return b;}
 Switch toggle(String label,String key,boolean initial){Switch s=new Switch(this);s.setText(label);s.setTextSize(18*font());s.setTextColor(TEXT);s.setPadding(0,dp(12),0,dp(12));s.setChecked(prefs.getBoolean(key,initial));s.setOnCheckedChangeListener((b,c)->prefs.edit().putBoolean(key,c).apply());body.addView(s);return s;}
 void home(){base("Запись экрана");state=text(RecordingService.status,18);body.addView(state);body.addView(text("Android 10+ · Видео сохраняется в Movies/ScreenRecorder",14));mic=toggle("Микрофон","mic",true);body.addView(text("Громкость микрофона",16));gain=new SeekBar(this);gain.setMax(100);gain.setProgress(prefs.getInt("gain",100));body.addView(gain);meter=text("Уровень микрофона: 0%",14);body.addView(meter);gain.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean u){prefs.edit().putInt("gain",p).apply();if(RecordingService.active!=null)RecordingService.active.setGain(p);meter.setText("Громкость: "+p+"%");}});gain.setEnabled(mic.isChecked());mic.setOnCheckedChangeListener((b,c)->{prefs.edit().putBoolean("mic",c).apply();gain.setEnabled(c);});internal=toggle("Звук телефона","internal",false);body.addView(text("Некоторые приложения запрещают запись внутреннего звука.",14));
  body.addView(text("Качество",16));quality=new Spinner(this);ArrayAdapter<String> q=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Лёгкое · до 720p · 15 кадров/с","Обычное · до 1080p · 30 кадров/с","Высокое · до 1080p · 60 кадров/с"});quality.setAdapter(q);quality.setSelection(prefs.getInt("quality",0));body.addView(quality);quality.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){prefs.edit().putInt("quality",n).apply();}});
  button("Захватить экран",()->request(),true);button("Пауза / Продолжить",()->control("pause"),false);button("Остановить и сохранить",()->control("stop"),false);button("Галерея записей",()->gallery(),false);button("Настройки обновлений",()->updates(),false);
 }
 void request(){if(RecordingService.active!=null){message("Запись уже идёт. Управляйте ею здесь или через уведомление.");return;}ArrayList<String> needed=new ArrayList<>();if((mic.isChecked()||internal.isChecked())&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)needed.add(Manifest.permission.RECORD_AUDIO);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)needed.add(Manifest.permission.POST_NOTIFICATIONS);if(!needed.isEmpty()){requestPermissions(needed.toArray(new String[0]),9);return;}startActivityForResult(((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).createScreenCaptureIntent(),10);}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==9){if((mic.isChecked()||internal.isChecked())&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){message("Для выбранных источников звука разрешите доступ к микрофону или выключите звук.");return;}request();}}
 public void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(r==10&&code==RESULT_OK&&data!=null){Intent s=new Intent(this,RecordingService.class).putExtra("result",code).putExtra("data",data).putExtra("mic",mic.isChecked()).putExtra("internal",internal.isChecked()).putExtra("gain",gain.getProgress()).putExtra("quality",quality.getSelectedItemPosition());startForegroundService(s);new Handler().postDelayed(()->moveTaskToBack(true),500);}}
 void control(String a){if(RecordingService.active!=null)startService(new Intent(this,RecordingService.class).setAction(a));else message("Сейчас запись не идёт");}
 void message(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("Понятно",null).show();}
 void gallery(){base("Галерея");button("← К записи",()->home(),false);int count=0;try(Cursor c=getContentResolver().query(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,new String[]{"_id","_display_name","duration"},"relative_path LIKE ? AND is_pending=0",new String[]{"Movies/ScreenRecorder%"},"date_added DESC")){while(c!=null&&c.moveToNext()){Uri uri=ContentUris.withAppendedId(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,c.getLong(0));String name=c.getString(1);button(name+" · "+(c.getLong(2)/1000)+" с",()->viewer(uri,name),false);count++;}}catch(Exception e){message("Не удалось открыть галерею: "+e.getMessage());}if(count==0)body.addView(text("Пока нет записей. После сохранения видео появится здесь.",18));}
 void viewer(Uri uri,String name){base("Просмотр и обрезка");body.addView(text(name,16));VideoView video=new VideoView(this);body.addView(video,new LinearLayout.LayoutParams(-1,dp(250)));MediaController controller=new MediaController(this);controller.setAnchorView(video);video.setMediaController(controller);video.setVideoURI(uri);video.setOnPreparedListener(p->{video.seekTo(1);});video.setOnErrorListener((m,w,e)->{message("Не удалось воспроизвести этот файл");return true;});body.addView(text("Начало и конец фрагмента, в секундах",16));EditText from=new EditText(this),to=new EditText(this);from.setTextColor(TEXT);to.setTextColor(TEXT);from.setInputType(8194);to.setInputType(8194);from.setText("0");try{MediaMetadataRetriever r=new MediaMetadataRetriever();r.setDataSource(this,uri);to.setText(String.format(Locale.US,"%.1f",Long.parseLong(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION))/1000.));r.release();}catch(Exception e){to.setText("1");}body.addView(from);body.addView(to);button("Начало — текущий кадр",()->from.setText(String.format(Locale.US,"%.1f",video.getCurrentPosition()/1000.)),false);button("Конец — текущий кадр",()->to.setText(String.format(Locale.US,"%.1f",video.getCurrentPosition()/1000.)),false);body.addView(text("Быстрая обрезка без потери качества. Начало привязывается к ближайшему следующему ключевому кадру.",14));Button export=button("Сохранить обрезанную копию",()->{try{double a=Double.parseDouble(from.getText().toString().replace(',','.')),b=Double.parseDouble(to.getText().toString().replace(',','.'));if(a<0||b<=a)throw new Exception("Проверьте начало и конец");new Thread(()->{try{Uri out=Trim.copy(this,uri,a,b);runOnUiThread(()->{message("Копия сохранена; исходник не изменён");gallery();});}catch(Exception e){runOnUiThread(()->message("Обрезка: "+e.getMessage()));}},"trim").start();}catch(Exception e){message(e.getMessage());}},true);button("Поделиться",()->{Intent i=new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Отправить видео"));},false);button("← Галерея",()->{video.stopPlayback();gallery();},false);}
 void updates(){base("Обновления");Switch stable=toggle("Только стабильные версии","stable",false);stable.setOnCheckedChangeListener((v,b)->{prefs.edit().putBoolean("stable",b).apply();Updater.check(this,true);});body.addView(text("По умолчанию скачиваются и тестовые сборки. Проверка выполняется при каждом возвращении в приложение. Установку подтверждает Android.",16));button("Проверить сейчас",()->Updater.check(this,true),true);button("← К записи",()->home(),false);}
 protected void onResume(){super.onResume();resumed=true;handler.post(tick);Updater.check(this,false);}
 protected void onPause(){super.onPause();resumed=false;handler.removeCallbacks(tick);}
 final Runnable tick=new Runnable(){public void run(){if(!resumed)return;if(state!=null)state.setText(RecordingService.status);if(mic!=null)mic.setEnabled(RecordingService.active==null);if(internal!=null)internal.setEnabled(RecordingService.active==null);if(quality!=null)quality.setEnabled(RecordingService.active==null);if(meter!=null&&RecordingService.active!=null)meter.setText("Уровень микрофона: "+RecordingService.level+"%");if(RecordingService.active==null&&!RecordingService.lastUri.isEmpty()&&!shown.equals(RecordingService.lastUri)){shown=RecordingService.lastUri;viewer(Uri.parse(shown),"Последняя запись");}handler.postDelayed(this,500);}};
}
